1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.function.owner.HouseholdTier;
6	
7	/**
8	 * Caps a new owner's membership level at one above the highest level among the household
9	 * members that already existed when they were created (same household — see
10	 * {@link HouseholdId} — and a lower, i.e. earlier, id). With no earlier household member
11	 * no cap applies and the raw level stands.
12	 */
13	public final class HouseholdCap {
14	
15	    private HouseholdCap() {
16	    }
17	
18	    public static int cap(Owner owner, int rawLevel, OwnerRepository ownerRepository) {
19	        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
20	        int ceiling = -1;
21	        for (Owner other : ownerRepository.findAll()) {
22	            if (isEarlierMember(owner, other, householdId)) {
23	                ceiling = Math.max(ceiling, cap(other, rawLevel(other, ownerRepository), ownerRepository));
24	            }
25	        }
26	        return ceiling < 0 ? rawLevel : Math.min(rawLevel, ceiling + 1);
27	    }
28	
29	    private static boolean isEarlierMember(Owner owner, Owner other, String householdId) {
30	        return owner.getId() != null && other.getId() != null && other.getId() < owner.getId()
31	                && householdId.equals(HouseholdId.of(other.getLastName(), other.getPostcode()));
32	    }
33	
34	    private static int rawLevel(Owner owner, OwnerRepository ownerRepository) {
35	        int points = MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(),
36	                owner.getRegistrationDate(), HouseholdTier.isGold(owner, ownerRepository));
37	        return MembershipLevel.of(points);
38	    }
39	}
