3	/**
4	 * Formats a stored E.164 telephone for humans: the country code, a space, then the
5	 * national digits grouped in threes (e.g. {@code +61412345678} => {@code +61 412 345
6	 * 678}). The country code mirrors the numbers produced when owners are created ('+1',
7	 * otherwise a two-digit code such as '+61'). Non-E.164 values are returned unchanged.
8	 */
9	public final class TelephoneDisplay {
10	
11	    private TelephoneDisplay() {
12	    }
13	
14	    public static String of(String telephone) {
15	        if (telephone == null || !telephone.startsWith("+")) {
16	            return telephone;
17	        }
18	        String digits = telephone.substring(1);
19	        String countryCode = digits.startsWith("1") ? "1" : digits.substring(0, 2);
20	        String national = digits.substring(countryCode.length());
21	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
22	        for (int i = 0; i < national.length(); i++) {
23	            grouped.append(i % 3 == 0 ? ' ' : "").append(national.charAt(i));
24	        }
25	        return grouped.toString();
26	    }
27	}
