1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.plugin.variable.Out;
5	import net.officefloor.server.http.HttpHeader;
6	import net.officefloor.server.http.ServerHttpConnection;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Entry step: routes an incoming create by its optional {@code Idempotency-Key}. A key
12	 * already seen (and whose owner still exists) branches to {@code existing} to return that
13	 * owner with 200; otherwise the key is published for later recording and {@code create}
14	 * runs the normal pipeline.
15	 */
16	public class RouteIdempotentCreate {
17	
18	    @FunctionalInterface
19	    public interface Create {
20	        void proceed();
21	    }
22	
23	    @FunctionalInterface
24	    public interface Existing {
25	        void repeat();
26	    }
27	
28	    public void service(ServerHttpConnection connection, IdempotencyStore store,
29	            OwnerRepository ownerRepository, Out<String> keyOut, Out<Owner> ownerOut,
30	            @Flow("create") Create create, @Flow("existing") Existing existing) {
31	        HttpHeader header = connection.getRequest().getHeaders().getHeader("Idempotency-Key");
32	        String key = header == null ? null : header.getValue();
33	        if (key != null) {
34	            Integer ownerId = store.find(key);
35	            if (ownerId != null) {
36	                Owner owner = ownerRepository.findById(ownerId);
37	                if (owner != null) {
38	                    ownerOut.set(owner);
39	                    existing.repeat();
40	                    return;
41	                }
42	            }
43	        }
44	        keyOut.set(key == null ? "" : key);
45	        create.proceed();
46	    }
47	}
